const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Wuhan location
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);
  const region = wuhan.buffer(50000); // 50km radius

  // Define time periods
  const feb2019 = ['2019-02-01', '2019-03-01'];
  const feb2020 = ['2020-02-01', '2020-03-01'];

  // Use Sentinel-5P Aerosol Index as proxy for PM2.5
  // Aerosol Index correlates with particulate matter
  const collection = 'COPERNICUS/S5P/OFFL/L3_AER_AI';

  // Function to filter and process
  function getAerosolData(dateRange) {
    const col = ee.ImageCollection(collection)
      .filterDate(dateRange[0], dateRange[1])
      .filterBounds(region)
      .select('absorbing_aerosol_index');

    return col;
  }

  // Get collections
  const col2019 = getAerosolData(feb2019);
  const col2020 = getAerosolData(feb2020);

  const size2019 = await col2019.size().getInfo();
  const size2020 = await col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  // Check if collections are empty
  if (size2019 === 0 && size2020 === 0) {
    console.log("No data for both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  if (size2019 === 0 || size2020 === 0) {
    console.log("No data for one period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean for each period
  const mean2019Image = col2019.mean();
  const mean2020Image = col2020.mean();

  // Reduce to get values
  const stats2019 = await mean2019Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = await mean2020Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  // Check pixel counts
  const count2019 = await mean2019Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const count2020 = await mean2020Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const val2019 = stats2019.absorbing_aerosol_index;
  const val2020 = stats2020.absorbing_aerosol_index;
  const pixels2019 = count2019.absorbing_aerosol_index;
  const pixels2020 = count2020.absorbing_aerosol_index;

  console.log(`2019 Mean AI: ${val2019}, Pixels: ${pixels2019}`);
  console.log(`2020 Mean AI: ${val2020}, Pixels: ${pixels2020}`);

  // Check for no valid pixels
  if (pixels2019 === 0 || pixels2020 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for null/invalid values
  if (val2019 === null || val2019 === undefined || isNaN(val2019) ||
      val2020 === null || val2020 === undefined || isNaN(val2020)) {
    console.log("Invalid calculation results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values - Higher aerosol index means more PM2.5
  // Note: During COVID-19 lockdown in Feb 2020, pollution decreased
  if (val2020 > val2019) {
    console.log("PM2.5 proxy higher in Feb 2020.");
    console.log("<answer>A</answer>");
  } else {
    console.log("PM2.5 proxy lower in Feb 2020.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
